Consider the following C program:

```c
#include <stdio.h>

int main() {
    int a = 6;
    int b = 0;
    while (a < 10) {
        a = a / 12 + 1;
        a += b;
    }
    printf("%d", a);
    return 0;
}
```

Which one of the following statements is correct?

Consider the following C program:

```c
#include <stdio.h>

void fX();

int main() {
    fX();
    return 0;
}

void fX() {
    char a;
    if ((a = getchar()) != '\n') {
        fX();
    }
    if (a != '\n') {
        putchar(a);
    }
}
```

Assume the program's input is `1234` followed by a newline. Which one of the following statements is correct?

